#include <stdio.h>
#include <string.h>

#define D 256
#define Q 101

int main() {
    char txt[100], pat[50];
    int pHash = 0, tHash = 0, h = 1, found = 0;

    printf("Enter text string (no spaces): ");
    scanf("%s", txt);
    printf("Enter pattern to search: ");
    scanf("%s", pat);

    int n = strlen(txt), m = strlen(pat);

    for (int i = 0; i < m - 1; i++) h = (h * D) % Q;

    for (int i = 0; i < m; i++) {
        pHash = (D * pHash + pat[i]) % Q;
        tHash = (D * tHash + txt[i]) % Q;
    }

    for (int i = 0; i <= n - m; i++) {
        if (pHash == tHash) {
            int j;
            for (j = 0; j < m; j++) {
                if (txt[i + j] != pat[j]) break;
            }
            if (j == m) {
                printf("Pattern found at index %d\n", i);
                found = 1;
            }
        }
        if (i < n - m) {
            tHash = (D * (tHash - txt[i] * h) + txt[i + m]) % Q;
            if (tHash < 0) tHash += Q;
        }
    }
    if (!found) printf("Pattern not found in text.\n");
    return 0;
}

